static_checks.command:
set -u
out="node_modules/.cache/bsf/typescript.sarif"
log="$(mktemp)"
conv="$(mktemp -t bsf-tsc-sarif-XXXXXX.cjs)"
mkdir -p "$(dirname "$out")"
rm -f "$out"
# tsc exits non-zero when it finds anything; the SARIF is what is counted.
node ./node_modules/typescript/bin/tsc -p tsconfig.json --noEmit --pretty false --incremental false > "$log" 2>&1 || true
cat > "$conv" <<'BSF_TSC_SARIF'
const fs = require("fs");
const path = require("path");
const [, , logPath, outPath] = process.argv;
const lines = fs.readFileSync(logPath, "utf8").split("\n");
const located = /^(.+?)\((\d+),(\d+)\): (error|warning) (TS\d+): (.*)$/;
const global = /^(error|warning) (TS\d+): (.*)$/;
const ids = new Set();
const results = [];
const add = (rule, level, message, file, line, col) => {
  ids.add(rule);
  results.push({
    ruleId: rule,
    level: level === "warning" ? "warning" : "error",
    message: { text: message },
    locations: [{ physicalLocation: {
      artifactLocation: { uri: file.split("\\").join("/") },
      region: { startLine: line, startColumn: col },
    } }],
  });
};
for (const raw of lines) {
  const line = raw.trimEnd();
  const m = located.exec(line);
  if (m) { add(m[5], m[4], m[6], m[1], Number(m[2]), Number(m[3])); continue; }
  const g = global.exec(line);
  if (g) { add(g[2], g[1], g[3], "tsconfig.json", 1, 1); }
}
const sarif = {
  $schema: "https://json.schemastore.org/sarif-2.1.0.json",
  version: "2.1.0",
  runs: [{
    tool: { driver: {
      name: "typescript",
      informationUri: "https://www.typescriptlang.org/",
      rules: [...ids].map((id) => ({ id })),
    } },
    results,
  }],
};
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, JSON.stringify(sarif, null, 2));
BSF_TSC_SARIF
node "$conv" "$log" "$out"
